    str     x30, [x9, #216]      // private: saved LR (+0xD8)
    str     x19, [x9, #224]      // private: saved x19 (+0xE0)
    mov     x19, x9
    msr     tpidr_el0, x10
    bl      \target
    ldr     x30, [x19, #216]
    msr     tpidr_el0, x19
    ldr     x19, [x19, #224]
    ret
.size \name, .-\name
.endm

